int restore_extended_state(struct xsave_struct *fx, u64 mask) {
    int error = 0;

    asm volatile (
        "1: xrstors %1, %2\n"
        "2:\n"
        ".section .fixup,\"ax\"\n"
        "3: mov %3, %0\n"
        "   jmp 2b\n"
        ".previous\n"
        : : "m"(error), "m"(*fx), "r"(mask), "i"(1)
        : "memory");

    return error;
}

int restore_extended_state(struct xsave_struct *fx, u64 mask) {
    int ret = 0;

    // Check if xrstors is available
    if (cpufeatures.xrstors_supported) {
        __asm__ __volatile__(
            "xrstors %0, %1\n"
            :
            : "m"(*fx), "r"(mask)
            : "memory");
    } else {
        __asm__ __volatile__(
            "xrstor %0\n"
            :
            : "m"(*fx)
            : "memory");
    }

    return ret;
}
